import csv,re,sys,itertools
inp,out=sys.argv[1:3]
rows=[]
with open(inp) as f:
 r=csv.DictReader(f,delimiter="\t")
 for x in r:
  if x["section"]!="correlation_log1p" or x["variant"]!="merge_DiMes_HyTh_into_neural": continue
  m=re.search(r"raw_cor=([^;]+);mae_cpm=([^;]+)",x["detail"])
  rows.append((x["observed"],x["reference"],float(x["value"]),float(m.group(1)),float(m.group(2))))
obs=sorted({x[0] for x in rows}); refs=sorted({x[1] for x in rows})
D={(a,b):(l,r,m) for a,b,l,r,m in rows}
def assignment(metric):
 n=len(obs); dp={0:(0.0,())}
 for i,a in enumerate(obs):
  nd={}
  for mask,(score,path) in dp.items():
   for j,b in enumerate(refs):
    if mask>>j&1: continue
    v=D[a,b][metric]
    nm=mask|1<<j; nv=score+v
    if nm not in nd or nv>nd[nm][0]: nd[nm]=(nv,path+(j,))
  dp=nd
 return dp[(1<<n)-1]
with open(out,"w") as f:
 f.write("section\tmetric\tobserved\treference\tvalue\tdetail\n")
 for mi,mn in [(0,"log1p_cor"),(1,"raw_cor")]:
  for a in obs:
   z=sorted([(D[a,b][mi],b) for b in refs],reverse=True)
   f.write("independent_best\t%s\t%s\t%s\t%.10g\tsecond=%s:%.10g\n"%(mn,a,z[0][1],z[0][0],z[1][1],z[1][0]))
  sc,path=assignment(mi)
  for i,j in enumerate(path): f.write("global_assignment\t%s\t%s\t%s\t%.10g\ttotal=%.10g\n"%(mn,obs[i],refs[j],D[obs[i],refs[j]][mi],sc))

